export const getPillar = (key: PillarKey) => PILLARS[key];

export const getClusterBySlug = (slug: string): ClusterMeta | undefined =>
 CLUSTER_ARTICLES.find((c) => c.slug === slug);

export const getSiblings = (slug: string, limit = 2): ClusterMeta[] => {
 const current = getClusterBySlug(slug);
 if (!current) return [];
 return CLUSTER_ARTICLES.filter((c) => c.pillar === current.pillar && c.slug !== slug).slice(0, limit);
};
